/** Tests FIRST; Java UNRUN. Actual detached original-USA data and common pure consumers only.
 * No Body/Movement/Frame/World/loading admission, actor, art service or gameplay claim.
 * Spy negatives deliberately contradict an authenticated public projection; no forged positive owner. */
class TestCdR31aPlayerCoreAssets {
 @Test void actualR3FactoryOwnsOnlyTheRetainedOriginalAndBorrowsIts167VisualProduct()throws Exception{var a=actual();var p=CdR11aPlayerAssets.fromR31aAssets(a.first());assertEquals(CdR11aPlayerAssets.SourceGraph.R3,p.sourceGraph());assertSame(a.first().sonic(),p.sonic());assertEquals(CdSonicVisualAssets.SourceFormat.FRAMES_167,p.sonic().sourceFormat());assertEquals(167,p.sonic().mappingFrames().size());assertEquals(57120,p.sonic().rawArt().length());assertEquals(57120,p.sonic().artReadView().length());assertThrows(IllegalStateException.class,p.sonic()::alignmentByte);assertTrue(p.ownsR31aAssets(a.first()));assertFalse(p.ownsR31aAssets(a.second()));assertFalse(p.ownsR31aAssets(null));assertNotSame(a.first(),a.second());assertEquals(a.first().identity(),a.second().identity());}
 @Test void actualFullCommonManifestsUseOnlyR31RawViewsAndBoundedLivePrefixes()throws Exception{var a=actual().first();var p=CdR11aPlayerAssets.fromR31aAssets(a);assertEquals(578,p.animationTable().length());assertEquals("96c145e86b5f841f36dbfca9361c7139df4ff5705423566836d361ace6098af9",hash(p.animationTable()));assertArrayEquals(a.view(CdR31aAssets.Asset.ANI_SONIC).copy(),p.animationTable().copy());assertEquals(60,p.miniAnimations().length());assertEquals("adcb220955503a487e05e9d1310f244e7c84e50c26c0fbf5c2a64e968f2f4c1a",hash(p.miniAnimations()));assertArrayEquals(a.view(CdR31aAssets.Asset.MINI_ANIMATIONS).slice(0,60).copy(),p.miniAnimations().copy());assertEquals(80,a.view(CdR31aAssets.Asset.MINI_ANIMATIONS).length());assertEquals("3324346eac28b3d6e05a8879c8fead0220a5fc1101fbbcefc3a4caa927c442f8",hash(a.view(CdR31aAssets.Asset.MINI_ANIMATIONS)));assertArrayEquals(a.view(CdR31aAssets.Asset.SPEC_CHUNKS).copy(),p.specialChunks().copy());assertEquals("365475d471c68745e3881c3743e1669911103607f18d88d9db7292e29177c0bf",hash(p.specialChunks()));assertEquals("bbde7b84eb90b56a2425842a67a0ff0316b3f3b0ff49b956f9b86c1267d75bb9",hash(p.sineTable()));assertEquals(640,p.sineTable().length());assertArrayEquals(a.view(CdR31aAssets.Asset.SINE_TABLE).copy(),p.sineTable().copy());assertEquals(257,p.arcTanTable().length());assertArrayEquals(a.view(CdR31aAssets.Asset.ARC_TAN_TABLE).slice(0,257).copy(),p.arcTanTable().copy());assertEquals(258,a.view(CdR31aAssets.Asset.ARC_TAN_TABLE).length());assertEquals("7d0ff986365e0596080368cab93935822e1f39220f50071db5dd075c0cabe66f",hash(a.view(CdR31aAssets.Asset.ARC_TAN_TABLE)));assertEquals(0x20,p.arcTanByte(256));assertEquals(0,a.view(CdR31aAssets.Asset.ARC_TAN_TABLE).unsignedByte(257));}
 @Test void everyScriptAndAliasRetainsNativeOrderAndAllSixLatentHighFrameBodies()throws Exception{var p=CdR11aPlayerAssets.fromR31aAssets(actual().first());var meta=new StringBuilder();var high=new ArrayList<Integer>();for(int id=0;id<60;id++){var body=p.animation(id);boolean unavailable=false;for(int i=1;i<body.bytes().length();i++){int v=body.bytes().unsignedByte(i);if(v>=253)break;if(v>=167)unavailable=true;}if(unavailable)high.add(id);meta.append(id).append(' ').append(Integer.toHexString(body.relativeOffset())).append(' ').append(body.bytes().length()).append(' ').append(hash(body.bytes())).append('\n');}assertEquals("b3a9b6e328ba28f85516828dc3f997da66052391cfe4a23a79907596e99f9125",CdR11aProfile.sha256(meta.toString().getBytes(StandardCharsets.UTF_8)));assertEquals(List.of(15,51,52,53,56,57),high);int[] ids={15,51,52,53,56,57};String[] bodies={"076162b963baff00","0301b5b5b6b6b7b7bbfd0500","0301b5b50101b8b8bbfd0500","ffa6a7a8a9ffffff","0179abacabacabaca9aaa9aaa9aaa7a8a7a8a7a8fd1a","015da7a8a7a8a7a8a9aaa9aaa9aaabacabacabacfd1a"};for(int i=0;i<ids.length;i++)assertEquals(bodies[i],HexFormat.of().formatHex(p.animation(ids[i]).bytes().copy()));assertEquals(p.animation(54).relativeOffset(),p.animation(58).relativeOffset());assertEquals(p.animation(55).relativeOffset(),p.animation(59).relativeOffset());assertThrows(UnsupportedOperationException.class,()->p.animations().clear());}
 @Test void missingPpzRampIsATypedBoundaryWithoutFallbackBytesOrMutation()throws Exception{var a=actual().first();var p=CdR11aPlayerAssets.fromR31aAssets(a);var table=p.animationTable();var rawMini=a.view(CdR31aAssets.Asset.MINI_ANIMATIONS);for(int i=0;i<2;i++){var e=assertThrows(CdR11aPlayerAssets.UnownedPpzRamp.class,p::rampChunks);assertTrue(e.getMessage().contains("R3"));}assertSame(table,p.animationTable());assertSame(rawMini,a.view(CdR31aAssets.Asset.MINI_ANIMATIONS));assertTrue(Arrays.stream(CdR31aAssets.Asset.values()).noneMatch(x->x.name().contains("RAMP")));assertTrue(Arrays.stream(CdR31aAssets.class.getDeclaredMethods()).noneMatch(x->x.getName().equals("player")));}
 @Test void realMathConsumesR31TablesWithNativeBoundsAndNoRampRead()throws Exception{var p=CdR11aPlayerAssets.fromR31aAssets(actual().first());var math=new CdPlayerMath(p);for(int angle=0;angle<256;angle++){var result=math.calcSine(angle|0xA500);assertEquals(p.sineWord(angle),result.sine());assertEquals(p.sineWord(angle+64),result.cosine());}assertEquals(0x20,math.calcAngle(1,1));assertEquals(0xA0,math.calcAngle(-1,-1));assertEquals(0x40,math.calcAngle(0,0));assertThrows(IndexOutOfBoundsException.class,()->p.sineWord(320));assertThrows(IndexOutOfBoundsException.class,()->p.arcTanByte(257));assertThrows(IndexOutOfBoundsException.class,()->p.miniAnimationId(60));assertThrows(IndexOutOfBoundsException.class,()->p.animation(60));}
 @Test void unchangedAnimationAdmitsLowFrameAndDefersThenRejectsActual185Atomically()throws Exception{var p=CdR11aPlayerAssets.fromR31aAssets(actual().first());var animation=new CdPlayerAnimation(p);var input=new CdPlayerAnimation.Input(15,0,0,0,0xA4,0,0);var start=new CdPlayerAnimation.State(15,0,0,0);assertEquals(new CdPlayerAnimation.State(15,1,7,0x61),animation.step(start,input).state());var pending=new CdPlayerAnimation.State(15,2,1,0x62);assertEquals(new CdPlayerAnimation.State(15,2,0,0x62),animation.step(pending,input).state());var selected=new CdPlayerAnimation.State(15,2,0,0x62);var before=hash(p.animationTable());var error=assertThrows(UnsupportedOperationException.class,()->animation.step(selected,input));assertTrue(error.getMessage().contains("Map frame 185 outside admitted Sonic mappings (167)"));assertEquals(new CdPlayerAnimation.State(15,2,0,0x62),selected);assertEquals(new CdPlayerAnimation.Input(15,0,0,0,0xA4,0,0),input);assertEquals(before,hash(p.animationTable()));assertThrows(UnsupportedOperationException.class,()->animation.step(new CdPlayerAnimation.State(15,0,1,185),input));}
 @Test void old198DecoderStillOwnsItsRealRampAndRejectsMalformedFramesEagerly()throws Exception{var p=actual().present().player();assertEquals(CdR11aPlayerAssets.SourceGraph.PPZ,p.sourceGraph());assertEquals(198,p.sonic().mappingFrames().size());assertEquals(6,p.rampChunks().length());assertFalse(p.ownsR31aAssets(actual().first()));byte[] raw=p.animationTable().copy();raw[0xDF]=(byte)198;var error=assertThrows(IllegalArgumentException.class,()->decode(p,raw,p.rampChunks().copy()));assertEquals("Animation frame outside Sonic mappings",error.getMessage());}
 @Test void oldRampExtentSentinelAndValidationOrderRemainStrict()throws Exception{var p=actual().present().player();for(byte[] raw:List.of(new byte[0],new byte[5]))assertEquals("3D ramp chunks extent",assertThrows(IllegalArgumentException.class,()->decode(p,p.animationTable().copy(),raw)).getMessage());var early=p.rampChunks().copy();early[0]=(byte)255;assertEquals("Early/invalid R11A ramp chunk sentinel",assertThrows(IllegalArgumentException.class,()->decode(p,p.animationTable().copy(),early)).getMessage());var missing=p.rampChunks().copy();missing[5]=0;assertEquals("Missing reviewed R11A ramp chunk sentinel",assertThrows(IllegalArgumentException.class,()->decode(p,p.animationTable().copy(),missing)).getMessage());var bad=p.animationTable().copy();bad[0]=(byte)255;bad[1]=(byte)254;assertEquals("Animation signed relative pointer outside reviewed bodies",assertThrows(IllegalArgumentException.class,()->decode(p,bad,new byte[0])).getMessage());assertThrows(NullPointerException.class,()->decode(p,p.animationTable().copy(),null));}
 @Test void commonRawProductsStayImmutableAfterProgrammeClose()throws Exception{var p=CdR11aPlayerAssets.fromR31aAssets(actual().first());for(var v:List.of(p.animationTable(),p.miniAnimations(),p.specialChunks(),p.sineTable(),p.arcTanTable())){var before=v.copy();Arrays.fill(v.copy(),(byte)0xA5);assertArrayEquals(before,v.copy());assertThrows(java.nio.ReadOnlyBufferException.class,()->v.buffer().put(0,(byte)1));}assertThrows(NullPointerException.class,()->CdR11aPlayerAssets.fromR31aAssets(null));}
 @Test void contradictoryVisualAndIdentityProjectionsCannotMintR3Products()throws Exception{var data=actual();var wrong=spy(data.first());doReturn(data.present().sonic()).when(wrong).sonic();assertThrows(IllegalArgumentException.class,()->CdR11aPlayerAssets.fromR31aAssets(wrong));var foreign=spy(data.first());var identity=mock(CdR31aAssets.Identity.class);when(identity.variant()).thenReturn(CdReleaseVariant.EUROPE);doReturn(identity).when(foreign).identity();assertThrows(IllegalArgumentException.class,()->CdR11aPlayerAssets.fromR31aAssets(foreign));}
 @Test void contradictoryPlayerTableProjectionsAreRejectedBeforeCommonParsing()throws Exception{var a=actual().first();for(var id:List.of(CdR31aAssets.Asset.ANI_SONIC,CdR31aAssets.Asset.MINI_ANIMATIONS,CdR31aAssets.Asset.SPEC_CHUNKS,CdR31aAssets.Asset.SINE_TABLE,CdR31aAssets.Asset.ARC_TAN_TABLE)){byte[] bytes=a.view(id).copy();switch(id){case ANI_SONIC->{bytes[0]=(byte)255;bytes[1]=(byte)254;}case MINI_ANIMATIONS->bytes[0]=60;case SPEC_CHUNKS->bytes=Arrays.copyOf(bytes,3);case SINE_TABLE->{bytes[0]=1;bytes[1]=1;}case ARC_TAN_TABLE->bytes[256]=0x21;default->throw new AssertionError(id);}var wrong=spy(a);doReturn(CdAssetBytes.copyOf(bytes)).when(wrong).view(id);assertThrows(IllegalArgumentException.class,()->CdR11aPlayerAssets.fromR31aAssets(wrong),id.name());}assertEquals("96c145e86b5f841f36dbfca9361c7139df4ff5705423566836d361ace6098af9",hash(a.view(CdR31aAssets.Asset.ANI_SONIC)));}
 private static CdR11aPlayerAssets decode(CdR11aPlayerAssets p,byte[] animations,byte[] ramps){return CdR11aPlayerAssets.decode(animations,p.miniAnimations().copy(),ramps,p.specialChunks().copy(),p.sineTable().copy(),p.arcTanTable().copy(),p.sonic());}
 static String hash(CdAssetBytes b){return CdR11aProfile.sha256(b.copy());}
 record Actual(CdR31aAssets first,CdR31aAssets second,CdR11aAssets present){}
 private static Actual retained;
 static synchronized Actual actual()throws Exception{if(retained!=null)return retained;String root=System.getProperty("soniccd.media.root");assumeTrue(root!=null&&!root.isBlank(),"Optional original USA CD media absent");Path cue;try(var paths=Files.list(Path.of(root).resolve("USA"))){var cues=paths.filter(x->x.getFileName().toString().toLowerCase(Locale.ROOT).endsWith(".cue")).toList();assertEquals(1,cues.size(),"Configured original USA directory needs one CUE");cue=cues.getFirst();}try(var p=CdProgramAssets.open(cue,Optional.of(CdReleaseVariant.USA),Optional.empty())){retained=new Actual(CdR31aAssets.fromPrograms(p,CdStagePayload.R31A.stage()),CdR31aAssets.fromPrograms(p,CdStagePayload.R31A.stage()),CdR11aAssetLoader.load(p,CdReleaseVariant.USA,CdStagePayload.R11A.stage()));}return retained;}
}
